import{z as A,x as B,o as t,c as p,q as l,j as s,D as n,d as r,s as E,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"排序网络","description":"","frontmatter":{"title":"排序网络","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sorting-networks.md","filePath":"cs/sorting-networks.md","lastUpdated":1791413859000}'),d={name:"cs/sorting-networks.md"};function h(m,a,c,g,D,u){const o=B("Mermaid");return t(),p("div",null,[a[2]||(a[2]=l('<h1 id="排序网络" tabindex="-1">排序网络 <a class="header-anchor" href="#排序网络" aria-label="Permalink to &quot;排序网络&quot;">​</a></h1><div class="epigraph"><p>比较器只交换两条线，数据无关控制；Batcher 双调 $O(\\log^2 n)$ 层，Ajtai–Komlós–Szemerédi $O(\\log n)$ 层存在但巨大。</p><footer>—— 据 Batcher, Sorting Networks and Their Applications, 1968；Ajtai, Komlós and Szemerédi, 1983；Knuth TAOCP 卷 3 整理</footer></div><p>上一课<a href="/cs/work-span-model">work-span</a>是任务 DAG 的成本模型；排序网络把并行推到极端：线路固定，每层比较器同时动作，控制流与数据完全无关。缺口是 0-1 原理与 Batcher 构造。本课不重写快排期望；后课对手论证给比较下界。Knuth 卷 3 是比较网络的标准出处。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>比较器 \\((i,j)\\)：若 \\(x_i\\gt x_j\\) 则交换两线，无分支、无数据依赖。0-1 原理：网络对任意输入正确 \\(\\Leftrightarrow\\) 对 0-1 输入正确——证明对象从 \\(n!\\) 种排列塌缩成 \\(n+1\\) 种 0-1 串。Batcher 用奇偶归并与双调排序做出 \\(O(\\log^2 n)\\) 层、\\(O(n\\log^2 n)\\) 个比较器的网络；AKS 证明 \\(O(\\log n)\\) 层存在，但常数巨大不实用。实践里 GPU 排序用的正是 Batcher 一族。</p><p>缺口是「无数据依赖的控制」，不是堆排序。</p><p><span class="marginnote">数字实例：0-1 原理的省力程度——\\(n=16\\) 时一般输入要考虑 \\(16!\\approx 2\\times10^{13}\\) 种排列，而 0-1 串只有 \\(17\\) 种，验证对象一下塌缩约 12 个数量级；这正是排序网络能被穷举验证的原因。</span></p><h3 id="不是比较次数-下界的紧实现" tabindex="-1">不是比较次数 \\(n\\log n\\) 下界的紧实现 <a class="header-anchor" href="#不是比较次数-下界的紧实现" aria-label="Permalink to &quot;不是比较次数 $n\\log n$ 下界的紧实现&quot;">​</a></h3><p>比较次数的信息下界 \\(\\Omega(n\\log n)\\) 与网络深度是两本账：AKS 的 \\(O(\\log n)\\) 层在并行深度上达到最优量级，但比较器总数与常数不实用——渐近胜利不等于工程胜利。</p><p><span class="marginnote">Batcher 1968。AKS 1983。Knuth TAOCP 卷 3。后课对手论证 \\(\\Omega(n\\log n)\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法是把线画出来：比较器层与连线构成图；正确性证明用 0-1 原理，把一般输入的检查化成对 0-1 串的检查；构造用双调递归——两个有序段接成双调序列后，归并网络递归拆半；最后数层数定深度。</p>',12)),(t(),s(i,null,{default:n(()=>[E(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22n%20%E6%9D%A1%E7%BA%BF%22%5D%20--%3E%20CMP%5B%22%E5%9B%BA%E5%AE%9A%E6%AF%94%E8%BE%83%E5%99%A8%E5%B1%82%22%5D%0A%20%20CMP%20--%3E%20OUT%5B%22%E6%9C%89%E5%BA%8F%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"插入式网络要 \\(O(n^2)\\) 层，只当教学样例。",-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"直觉类比：比较器像一个固定岔口——两条线各走各的，到点比大小，大者换到指定那条线，全程没有 if。正因控制与数据完全无关，同一层的所有比较器可以同时开工，网络「层数」这个并行深度概念才成立。")],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"机制的根是 0-1 原理：比较器的行为只依赖两元素的相对序，任何对一般输入的失败都能经单调映射在某个 0-1 输入上显现——0-1 全对则全对。双调归并为什么成立：双调序列（先升后降）前后半对应元素两两比较后，各剩一个子双调且全体有序位置确定，递归拆半即完成归并。与 work-span 对上账：一层恰是一步跨度，比较器总数是工作。与 PRAM 比：网络是更弱但更规则的并行模型，可以直接译成硬件。",-1)),(t(),s(i,null,{default:n(()=>[E(o,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E4%B8%80%E8%88%AC%E8%BE%93%E5%85%A5%3A%20n!%20%E7%A7%8D%E6%8E%92%E5%88%97%22%5D%20--%3E%20B%5B%220-1%20%E5%8E%9F%E7%90%86%3A%20%E5%8F%AA%E9%9C%80%E6%A3%80%E6%9F%A5%20n%2B1%20%E7%A7%8D%200-1%20%E4%B8%B2%22%5D%0A%20%20B%20--%3E%20C%5B%22%E5%AF%B9%E6%AF%8F%E4%B8%AA%200-1%20%E4%B8%B2%E8%B7%91%E4%B8%80%E9%81%8D%E7%BD%91%E7%BB%9C%22%5D%0A%20%20C%20--%3E%20D%7B%22%E8%BE%93%E5%87%BA%E7%9A%84%200%20%E6%98%AF%E5%90%A6%E5%85%A8%E5%9C%A8%201%20%E5%89%8D%E9%9D%A2%3F%22%7D%0A%20%20D%20--%20%22%E5%85%A8%E9%83%A8%E9%80%9A%E8%BF%87%22%20--%3E%20E%5B%22%E7%BD%91%E7%BB%9C%E5%AF%B9%E4%B8%80%E5%88%87%E8%BE%93%E5%85%A5%E6%AD%A3%E7%A1%AE%22%5D%0A%20%20D%20--%20%22%E4%BB%BB%E4%B8%80%E5%A4%B1%E8%B4%A5%22%20--%3E%20F%5B%220-1%20%E5%8F%8D%E4%BE%8B%E5%8D%B3%E4%B8%80%E8%88%AC%E5%8F%8D%E4%BE%8B%20%E7%BD%91%E7%BB%9C%E6%9C%89%E9%94%99%22%5D%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l('<p><span class="marginnote">这张图回答「凭什么查 0-1 串就能担保所有输入」：任何一般输入的错误，都能经一个单调映射落到某个 0-1 串上同样出错——所以 17 个串全过等价于 \\(n!\\) 种排列全过。验证从指数级缩到线性个案例。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不画 AKS 的 expander 构造，不写量子排序。后课默认：实用排序网络取 Batcher 的 \\(O(\\log^2 n)\\) 层。下一课对手论证。</p><p><span class="marginnote">常见误区：把网络深度当比较次数。深度是最坏情形下一个元素串行经过的比较层数（决定时延），比较器总数才是总工作量（\\(O(n\\log^2 n)\\)）；AKS 深度 \\(O(\\log n)\\) 却常数巨大——两个指标要分开读，混为一谈会误判实用性。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>数据无关比较器网络。</li><li>0-1 原理；Batcher \\(O(\\log^2 n)\\) 层。</li><li>AKS 渐近更深优、常数大。</li><li>出处：Batcher, 1968；AKS, 1983；Knuth TAOCP 卷 3。</li></ul>',6))])}const C=A(d,[["render",h]]);export{_ as __pageData,C as default};
